from pathlib import Path
import base64,datetime,hashlib,json,subprocess
files={'root_bootstrap.py': {'base64': '', 'sha256': '2adbf5c5c80edde416ae9bf8eb9ac27532dbbc7b1c2d148c5d458aafd0aca307'}, 'initial_preflight.py': {'base64': '', 'sha256': 'f5b8d252df52d9afd276015fa197af7a521280e64f674405b9c8320cd34d9aef'}, 'FILES_SHA256.json': {'base64': '', 'sha256': '889884dd1502dc67776731e6fc73b60a34c52595af9e3193a920a3cee9bba1c6'}, 'ROOT_GRADIENT14_ADOPTION.json': {'base64': '', 'sha256': 'b4ba8c8921bc6b63cfec5996149fb59a9abae41dfaba1e3b345c3d3d8b4c2bf5'}, 'ROOT_RUNTIME_AUTHORIZATION.json': {'base64': '', 'sha256': '5087049dc63019a42794ca4f8fbd7cd60588e3c193368afef5a39359fef25d83'}}
sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
assert sha('/etc/vast-agents-guide.md')=='42be4f7a84349c7bca6f6b35c10e94d70ddeb9239bcdeaf0c56317d4ab3fd2aa'
base=Path('/workspace/guardfed_checks/celeba_fednga96_bootstrap_20261011')
out=Path('/workspace/celeba_fednga_fullcoverage_results_20261011/attempt001')
assert not base.exists() and not out.exists()
service='guardfed_celeba_fednga_fullcoverage_v1'
status=subprocess.run(['supervisorctl','status',service],capture_output=True,text=True)
assert 'no such process' in status.stdout.lower() and status.returncode!=0,status.stdout+status.stderr
base.mkdir()
for n,row in files.items():
 raw=base64.b64decode(row['base64']);assert hashlib.sha256(raw).hexdigest()==row['sha256']
 with (base/n).open('xb') as f:f.write(raw)
 assert sha(base/n)==row['sha256']
frozen=Path('/workspace/guardfed_checks/celeba_gradient_fullcoverage_selected_20261011')
approval=frozen/'ROOT_SOURCE_APPROVAL.json';assert sha(approval)=='79edd0dde78c9dc23583a22953d3babebb357a4fcebb7197941cc5726b2ff961'
assert sha(frozen/'Fed-NGA-gradient/FILES_SHA256.json')=='06e3d638aea70123d7fcf73e5a219a0c0d3165c8cf60acb9dee4eace5faad09b'
root=base/'ROOT_GRADIENT14_ADOPTION.json';v=json.loads(root.read_bytes())
assert v['root_adoption'] and v['all14_offserver_verified'] and v['accepted_gate_jobs']==14
assert sha(v['scope_path'])==v['scope_sha256'] and sha(v['comparison_path'])==v['comparison_sha256']
cmd=['/usr/bin/env','CUDA_VISIBLE_DEVICES=1','GUARDFED_CPU_THREADS=1','OMP_NUM_THREADS=1','MKL_NUM_THREADS=1','OPENBLAS_NUM_THREADS=1','NUMEXPR_NUM_THREADS=1','PYTHONDONTWRITEBYTECODE=1','taskset','-c','105','nice','-n','10','ionice','-c','3','/workspace/guardfed_envs/celeba-cu128-20261009/bin/python','-B',str(base/'root_bootstrap.py'),'--out',str(out),'--receipt-dir',str(base/'actual001'),'--source-approval',str(approval),'--source-approval-sha256',sha(approval),'--gate14-adoption',str(root),'--gate14-adoption-sha256',sha(root)]
assert all(' ' not in a for a in cmd)
config=Path('/etc/supervisor/conf.d/'+service+'.conf');assert not config.exists()
text='[program:'+service+']\ncommand='+' '.join(cmd)+'\ndirectory=/workspace/GuardFed-celeba-expanded\nautostart=false\nautorestart=false\nstartsecs=0\nstartretries=0\nstopasgroup=true\nkillasgroup=true\nstdout_logfile='+str(base/'supervisor.stdout.log')+'\nstderr_logfile='+str(base/'supervisor.stderr.log')+'\n'
text=text.replace('\\n','\n')
with config.open('x') as f:f.write(text)
calls=[]
for argv in (['supervisorctl','reread'],['supervisorctl','update',service],['supervisorctl','start',service],['supervisorctl','status',service]):
 p=subprocess.run(argv,capture_output=True,text=True,timeout=25);calls.append(dict(argv=argv,returncode=p.returncode,stdout=p.stdout,stderr=p.stderr))
 with (base/'SUPERVISOR_COMMANDS.json').open('w') as f:json.dump(calls,f,indent=2)
 assert p.returncode==0,p.stdout+p.stderr
receipt=dict(status='NGA96_SUPERVISOR_ORIGINAL_BOOTSTRAP_STARTED_NOT_YET_SCIENTIFIC_ACCEPTANCE',utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),service=service,supervisor=calls,command=cmd,files={n:r['sha256'] for n,r in files.items()},config_sha256=sha(config),source_approval_sha256=sha(approval),root14_sha256=sha(root),new_jobs=96,reused_not_trained=4,automatic_retry=False,Huber_started=False,test=False)
with (base/'ROOT_START_RECEIPT.json').open('x') as f:json.dump(receipt,f,indent=2)
print(json.dumps(receipt))
